const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const store={get(k,f){try{return JSON.parse(localStorage.getItem(`qingliu:${k}`))??f}catch{return f}},set(k,v){localStorage.setItem(`qingliu:${k}`,JSON.stringify(v))}};
