function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function go(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===view));const item=$(`.nav-item[data-view="${view}"]`);$('#sectionEyebrow').textContent=item?.textContent.trim()||'控制台';$('#sectionTitle').textContent=view==='dashboard'?'早上好，今天想解决什么？':'所有判断都留在你手里';history.replaceState(null,'',`#${view}`);scrollTo({top:0,behavior:'smooth'})}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
$('#briefList').innerHTML=briefs.map(x=>`<div class="brief"><i></i><div><b>${x[0]}</b><span>${x[1]}</span></div><span class="tag">${x[2]}</span></div>`).join('');
$('#quickForm').addEventListener('submit',e=>{e.preventDefault();const text=$('#quickInput').value.trim();if(!text)return toast('先粘贴一段内容');const intent=$('#quickIntent').value;if(intent==='verify'){$('#verifyText').value=text;go('verify');$('#verifyBtn').click()}else if(intent==='save'){go('library');toast('已进入行动整理，可新建行动')}else{go('decide');toast('已进入消费比较')}});
function analyze(text){const claims=(text.match(/[。！？!?]/g)||[]).length+1;const danger=['绝对','保证','三天','根治','最低价','专家说','所有人','100%'].filter(w=>text.includes(w));const hasSource=/研究|报告|来源|医院|大学|链接|数据/.test(text);const hasAd=/购买|下单|优惠|直播间|同款|链接/.test(text);let score=82-danger.length*9-(hasSource?0:14)-(hasAd?8:0);score=Math.max(18,Math.min(96,score));return{score,claims,danger,hasSource,hasAd}}
$('#verifyBtn').addEventListener('click',()=>{const text=$('#verifyText').value.trim();if(!text)return toast('请先粘贴内容');const a=analyze(text);$('#verifyResult').innerHTML=`<div class="score-head"><div><p class="eyebrow">初步判断</p><h3>${a.score>=70?'信息可用，但仍需核对':'风险较高，不建议直接据此行动'}</h3></div><div class="score">${a.score}</div></div><p class="muted">识别出约 ${a.claims} 个可核查主张。分数是透明启发式结果，不代表事实真伪。</p><div class="check-list"><div class="check"><b>${a.hasSource?'✓':'!'} 来源</b>　${a.hasSource?'提到可追溯机构或数据，仍应打开原文。':'没有发现明确来源，请作者补充原始出处。'}</div><div class="check"><b>${a.danger.length?'!':'✓'} 表述</b>　${a.danger.length?`发现“${a.danger.join('、')}”等强断言。`:'未发现常见绝对化承诺。'}</div><div class="check"><b>${a.hasAd?'!':'✓'} 利益关系</b>　${a.hasAd?'可能包含交易引导，请确认是否为广告或佣金合作。':'未发现明显购买引导。'}</div><div class="check"><b>→ 下一步</b>　查找原始来源、发布日期、反方证据和适用人群。</div></div>`;store.set('lastVerify',{text,...a});$('#statVerify').textContent=Number($('#statVerify').textContent)+1;toast('核验卡已生成')});
function renderProducts(){$('#productTable').innerHTML=`<div class="compare-row head"><span>候选</span><span>到手价</span><span>退货成本</span><span>证据</span><span>操作</span></div>`+products.map((p,i)=>`<div class="compare-row"><b>${p.name}</b><span>¥${p.price}</span><span>¥${p.returnCost}</span><span class="evidence-${p.evidence==='高'?'high':p.evidence==='低'?'low':''}">${p.evidence}</span><button class="icon-btn" data-remove-product="${i}">移除</button></div>`).join('');$$('[data-remove-product]').forEach(b=>b.onclick=()=>{products.splice(+b.dataset.removeProduct,1);store.set('products',products);renderProducts()})}renderProducts();
$('#addProduct').onclick=()=>$('#productDialog').showModal();$('#productForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);products.push({name:f.get('name'),price:+f.get('price'),returnCost:+f.get('returnCost'),evidence:f.get('evidence')});store.set('products',products);renderProducts();$('#productDialog').close();e.target.reset();toast('已加入比较')});$('#cancelImpulse').onclick=e=>{e.target.closest('.cooldown').remove();toast('已记录：省下 ¥299')};
let selectedCollection=0;function renderCollections(){$('#collectionList').innerHTML=collections.map((c,i)=>`<button class="collection ${i===selectedCollection?'active':''}" data-collection="${i}"><b>${c.title}</b><span>${c.source} · ${c.tasks.filter(t=>t[1]).length}/${c.tasks.length} 完成</span></button>`).join('');$$('[data-collection]').forEach(b=>b.onclick=()=>{selectedCollection=+b.dataset.collection;renderCollections();renderAction()});renderAction();$('#statTasks').textContent=collections.reduce((n,c)=>n+c.tasks.filter(t=>!t[1]).length,0)}function renderAction(){const c=collections[selectedCollection];if(!c)return $('#actionDetail').innerHTML='<div class="empty-state"><p>新建一个行动计划</p></div>';$('#actionDetail').innerHTML=`<p class="eyebrow">行动计划</p><h2>${c.title}</h2><p class="muted">${c.source}</p><div>${c.tasks.map((t,i)=>`<label class="check-task ${t[1]?'done':''}"><input type="checkbox" data-task="${i}" ${t[1]?'checked':''}/><span>${t[0]}</span></label>`).join('')}</div>`;$$('[data-task]').forEach(x=>x.onchange=()=>{c.tasks[+x.dataset.task][1]=x.checked;store.set('collections',collections);renderCollections()})}renderCollections();$('#addCollection').onclick=()=>{const title=prompt('这组收藏最终要完成什么？');if(!title)return;collections.unshift({title,source:'手动创建',tasks:[['明确第一步',false],['设定完成时间',false]]});selectedCollection=0;store.set('collections',collections);renderCollections();toast('行动计划已创建')};
const topics=store.get('topics',{知识:80,本地:65,健康:45,娱乐:35,购物:15});function renderTopics(){$('#topicSliders').innerHTML=Object.entries(topics).map(([k,v])=>`<label class="slider-row"><span>${k}</span><input type="range" min="0" max="100" value="${v}" data-topic="${k}"/><b>${v}</b></label>`).join('');$$('[data-topic]').forEach(x=>x.oninput=()=>{topics[x.dataset.topic]=+x.value;x.nextElementSibling.textContent=x.value})}renderTopics();const bounds=['隐藏疾病焦虑内容','减少性别与地域对立','屏蔽未标注商业推广','夜间不推荐高刺激内容'];$('#boundaryList').innerHTML=bounds.map((b,i)=>`<label class="toggle-row"><span>${b}</span><input type="checkbox" ${i<3?'checked':''}/></label>`).join('');$('#saveFeed').onclick=()=>{store.set('topics',topics);toast('推荐偏好已保存')};$$('[data-mode]').forEach(b=>b.onclick=()=>{$('#modeStatus').textContent=`当前：${b.dataset.mode}${b.dataset.mode==='恢复默认'?'':'（临时）'}`;toast('模式已切换')});
function renderPlaces(list=places){$('#placeGrid').innerHTML=list.map(p=>`<article class="place-card"><span class="place-score">${p.score}</span><h3>${p.name}</h3><div class="place-meta">${p.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><p>${p.note}</p><button class="secondary wide">加入路线</button></article>`).join('');$$('.place-card button').forEach(b=>b.onclick=()=>toast('已加入本地行动清单'))}renderPlaces();$('#placeBtn').onclick=()=>{const q=$('#placeSearch').value.trim();const filtered=places.filter(p=>!q||`${p.name}${p.tags.join('')}${p.note}`.includes(q));renderPlaces(filtered);if(!filtered.length)$('#placeGrid').innerHTML='<div class="empty-state"><p>暂无完全匹配，试试更短的关键词。</p></div>'};
$('#filterComments').onclick=()=>{const lines=$('#commentText').value.split('\n').filter(Boolean),toxic=/傻|蠢|废物|女生就是|男人都|滚|有病/;$('#commentResult').innerHTML=lines.map(x=>`<div class="${toxic.test(x)?'removed':'kept'}">${toxic.test(x)?'已隐藏攻击：':'保留信息：'}${x}</div>`).join('')};$('#copySafety').onclick=async()=>{const t='直播购物前请先确认：1.只在平台内付款；2.看清退货规则；3.核验专家身份和最低价。';try{await navigator.clipboard.writeText(t);$('#copyStatus').textContent='已复制，可以发给家人。'}catch{$('#copyStatus').textContent=t}};$('#seniorMode').onchange=e=>{document.body.classList.toggle('senior',e.target.checked);store.set('senior',e.target.checked)};if(store.get('senior',false)){$('#seniorMode').checked=true;document.body.classList.add('senior')}
$('#exportBtn').onclick=()=>{const blob=new Blob([JSON.stringify({products,collections,topics,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='qingliu-data.json';a.click();URL.revokeObjectURL(a.href);toast('数据已导出')};
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'analyze_content',title:'分析短视频内容',description:'对用户提供的短视频文案进行透明的启发式风险检查。',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({text})=>{if(typeof text!=='string'||!text.trim())throw new Error('text must be non-empty');return analyze(text)}}).catch?.(()=>{});document.modelContext.registerTool({name:'set_feed_preferences',title:'设置推荐偏好',description:'批量设置本地保存的内容主题权重。',inputSchema:{type:'object',properties:{topics:{type:'object',additionalProperties:{type:'number',minimum:0,maximum:100}}},required:['topics'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({topics:next})=>{for(const [k,v] of Object.entries(next)){if(!Number.isFinite(v)||v<0||v>100)throw new Error('weights must be 0-100');topics[k]=v}store.set('topics',topics);renderTopics();return{saved:true,topics}}}).catch?.(()=>{})}
